<script setup>import {store,porcentaje} from '../store';</script><template><h2 class="mb-3">Progreso</h2><div class="card p-4"><h5>Cumplimiento general</h5><h2>{{porcentaje(store.tareas)}}%</h2><div class="progress mb-3"><div class="progress-bar" :style="{width:porcentaje(store.tareas)+'%'}"></div></div><p>{{store.tareas.filter(t=>t.estado==='Completado').length}} de {{store.tareas.length}} actividades completadas.</p><hr><h5>Avance por curso</h5><div v-for="c in store.cursos" :key="c.id" class="mb-3"><div class="d-flex justify-content-between"><span>{{c.nombre}}</span><span>{{porcentaje(store.tareas.filter(t=>t.curso===c.id))}}%</span></div><div class="progress"><div class="progress-bar" :style="{width:porcentaje(store.tareas.filter(t=>t.curso===c.id))+'%'}"></div></div></div></div></template>